import{_ as l,a0 as t,w as o,s as h,ao as d,I as p,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"精通 Linux 上的文件搜索 | LCTT x X-CMD","titleTemplate":false,"description":"精通 Linux 上的文件搜索 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精通 Linux 上的文件搜索 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精通 Linux 上的文件搜索 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170921 Mastering file searches on Linux","title":"精通 Linux 上的文件搜索","tag":"201801","desc":""},"relativePath":"201801/20170921 Mastering file searches on Linux.md","filePath":"[post].md"}'),r={name:"201801/20170921 Mastering file searches on Linux.md"};function c(g,s,k,u,b,m){const e=t("Link");return o(),h("div",null,[s[13]||(s[13]=d(`<h1 id="精通-linux-上的文件搜索" tabindex="-1">精通 Linux 上的文件搜索 <a class="header-anchor" href="#精通-linux-上的文件搜索" aria-label="Permalink to “精通 Linux 上的文件搜索”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2017/09/telescope-100736548-large.jpg" alt=""></p><p>在 Linux 系統上搜索文件的方法有很多，有的命令很簡單，有的很詳細。我們的目標是：縮小搜索範圍，找到您正在尋找的文件，又不受其他文件的干擾。在今天的文章中，我們將研究一些對文件搜索最有用的命令和選項。我們將涉及：</p><ul><li>快速搜索</li><li>更復雜的搜索條件</li><li>組合條件</li><li>反轉條件</li><li>簡單和詳細的回應</li><li>尋找重複的文件</li></ul><p>有很多有用的命令可以搜索文件，<code>find</code> 命令可能是其中最有名的，但它不是唯一的命令，也不一定總是找到目標文件的最快方法。</p><h3 id="快速搜索命令-which-和-locate" tabindex="-1">快速搜索命令：which 和 locate <a class="header-anchor" href="#快速搜索命令-which-和-locate" aria-label="Permalink to “快速搜索命令：which 和 locate”">​</a></h3><p>搜索文件的最簡單的命令可能就是 <code>which</code> 和 <code>locate</code> 了，但二者都有一些侷限性。<code>which</code> 命令只會在系統定義的搜索路徑中，查找可執行的文件，通常用於識別命令。如果您對輸入 <code>which</code> 時會運行哪個命令感到好奇，您可以使用命令 <code>which which</code>，它會指出對應的可執行文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which which</span></span>
<span class="line"><span>/usr/bin/which</span></span></code></pre></div><p><code>which</code> 命令會顯示它找到的第一個以相應名稱命名的可執行文件（也就是使用該命令時將運行的那個文件），然後停止。</p><p><code>locate</code> 命令更大方一點，它可以查找任意數量的文件，但它也有一個限制：僅當文件名被包含在由 <code>updatedb</code> 命令構建的資料庫時才有效。該文件可能會存儲在某個位置，如 <code>/var/lib/mlocate/mlocate.db</code>，但不能用 <code>locate</code> 以外的任何命令讀取。這個文件的更新通常是通過每天通過 cron 運行的 <code>updatedb</code> 進行的。</p><p>簡單的 <code>find</code> 命令沒有太多限制，不過它需要指定搜索的起點和搜索條件。最簡單的 <code>find</code> 命令：按文件名搜索文件。如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme</span></span>
<span class="line"><span>./bin/runme</span></span></code></pre></div><p>如上所示，通過文件名搜索文件系統的當前位置將會搜索所有子目錄，除非您指定了搜索深度。</p><h3 id="不僅僅是文件名" tabindex="-1">不僅僅是文件名 <a class="header-anchor" href="#不僅僅是文件名" aria-label="Permalink to “不僅僅是文件名”">​</a></h3><p><code>find</code> 命令允許您搜索除文件名以外的多種條件，包括文件所有者、組、權限、大小、修改時間、缺少所有者或組，和文件類型等。除了查找文件外，您還可以刪除文件、對其進行重命名、更改所有者、更改權限和對找到的文件運行幾乎任何命令。</p><p>下面兩條命令會查找：在當前目錄中 root 用户擁有的文件，以及不被指定用户（在本例中為 shs）所擁有的文件。在這個例子中，兩個輸出是一樣的，但並不總是如此。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -user root -ls</span></span>
<span class="line"><span> 396926 0 lrwxrwxrwx 1 root root 21 Sep 21 09:03 ./xyz -&gt; /home/peanut/xyz</span></span>
<span class="line"><span>$ find . ! -user shs -ls</span></span>
<span class="line"><span> 396926 0 lrwxrwxrwx 1 root root 21 Sep 21 09:03 ./xyz -&gt; /home/peanut/xyz</span></span></code></pre></div><p>感嘆號 <code>!</code> 字符代表“非”：反轉跟隨其後的條件。</p><p>下面的命令將查找具有特定權限的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -perm 750 -ls</span></span>
<span class="line"><span> 397176 4 -rwxr-x--- 1 shs shs 115 Sep 14 13:52 ./ll</span></span>
<span class="line"><span> 398209 4 -rwxr-x--- 1 shs shs 117 Sep 21 08:55 ./get-updates</span></span>
<span class="line"><span> 397145 4 drwxr-x--- 2 shs shs 4096 Sep 14 15:42 ./newdir</span></span></code></pre></div><p>接下來的命令顯示具有 777 權限的非符號鏈接文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -perm 777 ! -type l -ls</span></span>
<span class="line"><span> 397132 4 -rwxrwxrwx 1 shs shs 18 Sep 15 16:06 /home/shs/bin/runme</span></span>
<span class="line"><span> 396949 4 -rwxrwxrwx 1 root root 558 Sep 21 11:21 /home/oops</span></span></code></pre></div><p>以下命令將查找大小超過千兆字節的文件。請注意，我們找到了一個非常有趣的文件。它以 ELF core 文件格式表示了該系統的物理內存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find / -size +1G -ls</span></span>
<span class="line"><span> 4026531994 0 -r-------- 1 root root 140737477881856 Sep 21 11:23 /proc/kcore</span></span>
<span class="line"><span> 1444722 15332 -rw-rw-r-- 1 shs shs 1609039872 Sep 13 15:55 /home/shs/Downloads/ubuntu-17.04-desktop-amd64.iso</span></span></code></pre></div><p>只要您知道 <code>find</code> 命令是如何描述文件類型的，就可以通過文件類型來查找文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b = 塊設備文件</span></span>
<span class="line"><span>c = 字符設備文件</span></span>
<span class="line"><span>d = 目錄</span></span>
<span class="line"><span>p = 命名管道</span></span>
<span class="line"><span>f = 常規文件</span></span>
<span class="line"><span>l = 符號鏈接</span></span>
<span class="line"><span>s = 套接字</span></span>
<span class="line"><span>D = 門（僅限 Solaris）</span></span></code></pre></div><p>在下面的命令中，我們要尋找符號鏈接和套接字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l -ls</span></span>
<span class="line"><span> 396926 0 lrwxrwxrwx 1 root root 21 Sep 21 09:03 ./whatever -&gt; /home/peanut/whatever</span></span>
<span class="line"><span>$ find . -type s -ls</span></span>
<span class="line"><span> 395256 0 srwxrwxr-x 1 shs shs 0 Sep 21 08:50 ./.gnupg/S.gpg-agent</span></span></code></pre></div><p>您還可以根據 inode 號來搜索文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -inum 397132 -ls</span></span>
<span class="line"><span> 397132 4 -rwx------ 1 shs shs 18 Sep 15 16:06 ./bin/runme</span></span></code></pre></div><p>另一種通過 inode 搜索文件的方法是使用 <code>debugfs</code> 命令。在大的文件系統上，這個命令可能比 <code>find</code> 快得多，您可能需要安裝 icheck。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo debugfs -R &#39;ncheck 397132&#39; /dev/sda1</span></span>
<span class="line"><span>debugfs 1.42.13 (17-May-2015)</span></span>
<span class="line"><span>Inode Pathname</span></span>
<span class="line"><span>397132 /home/shs/bin/runme</span></span></code></pre></div><p>在下面的命令中，我們從主目錄（<code>~</code>）開始，限制搜索的深度（即我們將搜索子目錄的層數），並只查看在最近一天內創建或修改的文件（<code>mtime</code> 設置）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -maxdepth 2 -mtime -1 -ls</span></span>
<span class="line"><span> 407928 4 drwxr-xr-x 21 shs shs 4096 Sep 21 12:03 /home/shs</span></span>
<span class="line"><span> 394006 8 -rw------- 1 shs shs 5909 Sep 21 08:18 /home/shs/.bash_history</span></span>
<span class="line"><span> 399612 4 -rw------- 1 shs shs 53 Sep 21 08:50 /home/shs/.Xauthority</span></span>
<span class="line"><span> 399615 4 drwxr-xr-x 2 shs shs 4096 Sep 21 09:32 /home/shs/Downloads</span></span></code></pre></div><h3 id="不僅僅是列出文件" tabindex="-1">不僅僅是列出文件 <a class="header-anchor" href="#不僅僅是列出文件" aria-label="Permalink to “不僅僅是列出文件”">​</a></h3><p>使用 <code>-exec</code> 選項，在您使用 <code>find</code> 命令找到文件後可以以某種方式更改文件。您只需參照 <code>-exec</code> 選項即可運行相應的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme -exec chmod 700 {} \\;</span></span>
<span class="line"><span>$ find . -name runme -ls</span></span>
<span class="line"><span> 397132 4 -rwx------ 1 shs shs 18 Sep 15 16:06 ./bin/runme</span></span></code></pre></div><p>在這條命令中，<code>{}</code> 代表文件名。此命令將更改當前目錄和子目錄中任何名為 <code>runme</code> 的文件的權限。</p><p>把您想運行的任何命令放在 <code>-exec</code> 選項之後，並使用類似於上面命令的語法即可。</p><h3 id="其他搜索條件" tabindex="-1">其他搜索條件 <a class="header-anchor" href="#其他搜索條件" aria-label="Permalink to “其他搜索條件”">​</a></h3><p>如上面的例子所示，您還可以通過其他條件進行搜索：文件的修改時間、所有者、權限等。以下是一些示例。</p><h4 id="根據用户查找文件" tabindex="-1">根據用户查找文件 <a class="header-anchor" href="#根據用户查找文件" aria-label="Permalink to “根據用户查找文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -user peanut</span></span>
<span class="line"><span>/home/peanut</span></span>
<span class="line"><span>/home/peanut/.bashrc</span></span>
<span class="line"><span>/home/peanut/.bash_logout</span></span>
<span class="line"><span>/home/peanut/.profile</span></span>
<span class="line"><span>/home/peanut/examples.desktop</span></span></code></pre></div><h4 id="根據權限查找文件" tabindex="-1">根據權限查找文件 <a class="header-anchor" href="#根據權限查找文件" aria-label="Permalink to “根據權限查找文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -perm 777</span></span>
<span class="line"><span>/home/shs/whatever</span></span>
<span class="line"><span>/home/oops</span></span></code></pre></div><h4 id="根據修改時間查找文件" tabindex="-1">根據修改時間查找文件 <a class="header-anchor" href="#根據修改時間查找文件" aria-label="Permalink to “根據修改時間查找文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -mtime +100</span></span>
<span class="line"><span>/home/shs/.mozilla/firefox/krsw3giq.default/gmp-gmpopenh264/1.6/gmpopenh264.info</span></span>
<span class="line"><span>/home/shs/.mozilla/firefox/krsw3giq.default/gmp-gmpopenh264/1.6/libgmpopenh264.so</span></span></code></pre></div><h4 id="通過比較修改時間查找文件" tabindex="-1">通過比較修改時間查找文件 <a class="header-anchor" href="#通過比較修改時間查找文件" aria-label="Permalink to “通過比較修改時間查找文件”">​</a></h4><p>像這樣的命令可以讓您找到修改時間較近的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /var/log -newer /var/log/syslog</span></span>
<span class="line"><span>/var/log/auth.log</span></span></code></pre></div><h3 id="尋找重複的文件" tabindex="-1">尋找重複的文件 <a class="header-anchor" href="#尋找重複的文件" aria-label="Permalink to “尋找重複的文件”">​</a></h3><p>如果您正在清理磁盤空間，則可能需要刪除較大的重複文件。確定文件是否真正重複的最好方法是使用 <code>fdupes</code> 命令。此命令使用 md5 校驗和來確定文件是否具有相同的內容。使用 <code>-r</code>（遞歸）選項，<code>fdupes</code> 將在一個目錄下並查找具有相同校驗和而被確定為內容相同的文件。</p><p>如果以 root 身份運行這樣的命令，您可能會發現很多重複的文件，但是很多文件都是創建時被添加到主目錄的啓動文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># fdupes -rn /home &gt; /tmp/dups.txt</span></span>
<span class="line"><span># more /tmp/dups.txt</span></span>
<span class="line"><span>/home/jdoe/.profile</span></span>
<span class="line"><span>/home/tsmith/.profile</span></span>
<span class="line"><span>/home/peanut/.profile</span></span>
<span class="line"><span>/home/rocket/.profile</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/home/jdoe/.bashrc</span></span>
<span class="line"><span>/home/tsmith/.bashrc</span></span>
<span class="line"><span>/home/peanut/.bashrc</span></span>
<span class="line"><span>/home/rocket/.bashrc</span></span></code></pre></div><p>同樣，您可能會在 <code>/usr</code> 中發現很多重複的但不該刪除的配置文件。所以，請謹慎利用 <code>fdupes</code> 的輸出。</p><p><code>fdupes</code> 命令並不總是很快，但是要記住，它正在對許多文件運行校驗和來做比較，你可能會意識到它是多麼有效。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>有很多方法可以在 Linux 系統上查找文件。如果您可以描述清楚您正在尋找什麼，上面的命令將幫助您找到目標。</p><hr>`,59)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.networkworld.com/article/3227075/linux/mastering-file-searches-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3227075/linux/mastering-file-searches-on-linux.html",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=a("作者：",-1)),n(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),n(e,{href:"https://github.com/jessie-pang"},{default:i(()=>[...s[3]||(s[3]=[a("jessie-pang",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const y=l(r,[["render",c]]);export{w as __pageData,y as default};
